<script lang="ts">
 import type {DetailControl} from './detail-types';
 let {control,text,draftValue,disabled=false,idPrefix,error='',ontext,onDraft}:{control:DetailControl;text:string;draftValue?:unknown;disabled?:boolean;idPrefix:string;error?:string;ontext:(text:string)=>void;onDraft?:(value:unknown)=>void}=$props();
 const codes=[...Array.from({length:26},(_,i)=>'Key'+String.fromCharCode(65+i)),...Array.from({length:10},(_,i)=>'Digit'+i),...Array.from({length:12},(_,i)=>'F'+(i+1))];
 const modifiers=['ctrl','alt','shift','meta'] as const;
 let raw=$state(false);
 function hotkey(){try{const value=draftValue===undefined?JSON.parse(text):draftValue;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length!==5||!codes.includes(value.code)||modifiers.some(key=>typeof value[key]!=='boolean'))return null;return value as {code:string;ctrl:boolean;alt:boolean;shift:boolean;meta:boolean};}catch{return null;}}
 const value=$derived(hotkey());
 function change(key:string,next:string|boolean){if(disabled||!value)return;const draft={...value,[key]:next};if(onDraft)onDraft(draft);else ontext(JSON.stringify(draft,null,2));}
 const shown=$derived(raw&&draftValue!==undefined?JSON.stringify(draftValue,null,2):text);
</script>
<button type="button" aria-label={'Edit '+control.label+' as '+(raw||!value?'fields':'JSON')} disabled={disabled||!value} onclick={()=>{if(!disabled&&value)raw=!raw;}}>{raw||!value?'Use fields':'Advanced JSON'}</button>
{#if raw||!value}<label for={idPrefix+'-raw'}>{control.label} (Advanced JSON)</label><textarea id={idPrefix+'-raw'} aria-label={control.label} value={shown} {disabled} aria-invalid={!!error} aria-describedby={error?idPrefix+'-error':undefined} oninput={event=>{if(!disabled){raw=true;ontext(event.currentTarget.value);}}}></textarea>{#if !value}<small>This shape needs Advanced JSON. Authored values are retained.</small>{/if}
{:else}<label for={idPrefix+'-key'}>Physical key</label><select id={idPrefix+'-key'} aria-label="Physical key" value={value.code} {disabled} onchange={event=>change('code',event.currentTarget.value)}>{#each codes as code}<option value={code}>{code.startsWith('Key')?code.slice(3):code.startsWith('Digit')?code.slice(5):code}</option>{/each}</select>{#each modifiers as modifier}<label><input type="checkbox" aria-label={modifier==='ctrl'?'Ctrl':modifier[0].toUpperCase()+modifier.slice(1)} checked={value[modifier]} {disabled} onchange={event=>change(modifier,event.currentTarget.checked)} /> {modifier==='ctrl'?'Ctrl':modifier[0].toUpperCase()+modifier.slice(1)}</label>{/each}<small>Use Ctrl, Alt or Meta, or choose F1–F12. R is reserved for Run to here.</small>{/if}
<style>label,small{display:block;font-size:12px;margin:5px 0;}select,textarea{box-sizing:border-box;width:100%;padding:6px;background:var(--pc-field);color:var(--pc-text);border:1px solid var(--pc-border);font:inherit;}textarea{min-height:100px;resize:vertical;}button{padding:4px 6px;background:var(--pc-control);color:var(--pc-text);border:1px solid var(--pc-border);font:inherit;}small{color:var(--pc-muted);} :disabled{opacity:.55;} :is(select,textarea,button,input):focus-visible{outline:2px solid var(--pc-accent);outline-offset:1px;}</style>
